/**
 * IndexedDB persistence — LOTE 3 §3, multi-project since LOTE 5 §3.
 *
 * `projects` — every saved AnalysisProject, keyed by its own `id` (already
 *   generated by core/model.js's createProject). Replaces the LOTE 3
 *   single-active-project model: that matched how the app was used back
 *   then (one photo set at a time), but a commercial tool needs more than
 *   one client/athlete on the device without one overwriting another — see
 *   ESTADO.md, LOTE 5 §3.
 * `meta`     — one row, `activeProjectId`, pointing at whichever project the
 *   UI currently has open. Not the source of truth on its own: it is a
 *   resume pointer.
 * `blobs`    — original photo Blobs, keyed by `imageId` (a model-generated
 *   UUID). NOT by filename: two photos can share a filename, and a filename
 *   is itself a personal-data channel nobody decided to open (LOTE 3 audit).
 *   Shared across all projects; deleteProject below removes only the blobs
 *   that project's own images reference.
 *
 * Every export here tolerates IndexedDB being unavailable or throwing
 * (private browsing, a blocked/evicted origin, an aborted transaction) by
 * resolving to null / false rather than throwing into caller code that has
 * no recovery path anyway.
 */

const DB_NAME = 'angle-lab-db';
const DB_VERSION = 2;
const PROJECTS_STORE = 'projects';
const BLOB_STORE = 'blobs';
const META_STORE = 'meta';
const ACTIVE_PROJECT_ID_KEY = 'activeProjectId';

// v1-only: a single project lived here under this fixed key. Referenced
// only by the v1->v2 upgrade step below, which moves it into PROJECTS_STORE
// and then removes this store — nothing else should ever read from it again.
const LEGACY_PROJECT_STORE = 'project';
const LEGACY_ACTIVE_KEY = 'active';

let dbPromise = null;

function openDb() {
  if (dbPromise) return dbPromise;
  dbPromise = new Promise((resolve, reject) => {
    if (typeof indexedDB === 'undefined') {
      reject(new Error('indexedDB is not available'));
      return;
    }
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = (event) => {
      const db = request.result;
      const tx = request.transaction;
      if (event.oldVersion < 1) {
        if (!db.objectStoreNames.contains(BLOB_STORE)) {
          db.createObjectStore(BLOB_STORE, { keyPath: 'imageId' });
        }
      }
      if (event.oldVersion < 2) {
        if (!db.objectStoreNames.contains(PROJECTS_STORE)) {
          db.createObjectStore(PROJECTS_STORE, { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains(META_STORE)) {
          db.createObjectStore(META_STORE);
        }
        // One-way, runs once, same spirit as core/model.js's MIGRATIONS for
        // a project's own shape — this is the storage-layer equivalent for
        // going from one project to many. A fresh install has no
        // LEGACY_PROJECT_STORE at all, so this whole block is a no-op for
        // anyone who never had v1 data.
        if (db.objectStoreNames.contains(LEGACY_PROJECT_STORE)) {
          const legacyStore = tx.objectStore(LEGACY_PROJECT_STORE);
          const getReq = legacyStore.get(LEGACY_ACTIVE_KEY);
          getReq.onsuccess = () => {
            const legacyProject = getReq.result;
            if (legacyProject && legacyProject.id) {
              tx.objectStore(PROJECTS_STORE).put(legacyProject);
              tx.objectStore(META_STORE).put(legacyProject.id, ACTIVE_PROJECT_ID_KEY);
            }
            db.deleteObjectStore(LEGACY_PROJECT_STORE);
          };
        }
      }
    };
    request.onsuccess = () => {
      // Without this, a stale tab/PWA instance left open on the old schema
      // holds its connection forever, and any OTHER tab's attempt to open
      // this same database at a newer DB_VERSION queues behind it and never
      // completes — not an error, just silence, since IndexedDB reports it
      // as "blocked" rather than throwing. Closing our own connection on
      // its own versionchange event is the documented way out: it lets
      // whichever tab is actually current release the lock for the one
      // that just requested the upgrade.
      request.result.onversionchange = () => request.result.close();
      resolve(request.result);
    };
    request.onerror = () => reject(request.error);
  });
  return dbPromise;
}

function runRequest(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function withStore(storeName, mode, fn) {
  try {
    const db = await openDb();
    const tx = db.transaction(storeName, mode);
    const store = tx.objectStore(storeName);
    const result = await fn(store);
    await new Promise((resolve, reject) => {
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
      tx.onabort = () => reject(tx.error || new Error('transaction aborted'));
    });
    return result;
  } catch (error) {
    return { failed: true, error };
  }
}

// serializedProject is plain JSON (model.js's serialize output) — never the
// live project object, so a save can never race a caller still mutating it.
// Stored under the project's own `id`: saving twice with the same id
// overwrites that one project, never another.
export async function saveProject(serializedProject) {
  const result = await withStore(PROJECTS_STORE, 'readwrite', (store) =>
    runRequest(store.put(serializedProject))
  );
  return !(result && result.failed);
}

export async function loadProject(id) {
  if (!id) return null;
  const result = await withStore(PROJECTS_STORE, 'readonly', (store) => runRequest(store.get(id)));
  if (result && result.failed) return null;
  return result ?? null;
}

// Also removes this project's own photo Blobs — otherwise deleting a
// project would free none of the space it was actually holding.
export async function deleteProject(id) {
  const project = await loadProject(id);
  const imageIds = project && Array.isArray(project.images) ? project.images.map((img) => img.id) : [];
  const result = await withStore(PROJECTS_STORE, 'readwrite', (store) => runRequest(store.delete(id)));
  for (const imageId of imageIds) {
    await withStore(BLOB_STORE, 'readwrite', (store) => runRequest(store.delete(imageId)));
  }
  return !(result && result.failed);
}

// Lightweight summaries only, for a history list — it should not have to
// load every project's full points/measurements just to paint itself.
export async function listProjects() {
  const result = await withStore(PROJECTS_STORE, 'readonly', (store) => runRequest(store.getAll()));
  if (result && result.failed) return [];
  return (result || []).map((p) => ({
    id: p.id,
    subjectCode: p.subjectCode || '',
    title: p.title || '',
    createdAt: p.createdAt,
    updatedAt: p.updatedAt,
    imageCount: Array.isArray(p.images) ? p.images.length : 0,
  }));
}

export async function getActiveProjectId() {
  const result = await withStore(META_STORE, 'readonly', (store) => runRequest(store.get(ACTIVE_PROJECT_ID_KEY)));
  if (result && result.failed) return null;
  return result ?? null;
}

export async function setActiveProjectId(id) {
  const result = await withStore(META_STORE, 'readwrite', (store) =>
    runRequest(store.put(id, ACTIVE_PROJECT_ID_KEY))
  );
  return !(result && result.failed);
}

// Compatibility wrappers over the pointer + multi-project stores above, so
// the autosave loop and startup restore in ui/app.js don't need to know
// multi-project storage exists underneath them.
export async function loadActiveProject() {
  const id = await getActiveProjectId();
  if (!id) return null;
  return loadProject(id);
}

export async function saveActiveProject(serializedProject) {
  const ok = await saveProject(serializedProject);
  if (!ok) return false;
  return setActiveProjectId(serializedProject.id);
}

export async function saveBlob(imageId, blob) {
  const result = await withStore(BLOB_STORE, 'readwrite', (store) => runRequest(store.put({ imageId, blob })));
  return !(result && result.failed);
}

// LOTE 6: drops one photo's Blob (when that photo is deleted from its project). Same tolerance as
// saveBlob: false if IndexedDB failed, never a throw.
export async function deleteBlob(imageId) {
  const result = await withStore(BLOB_STORE, 'readwrite', (store) => runRequest(store.delete(imageId)));
  return !(result && result.failed);
}

export async function loadBlob(imageId) {
  const result = await withStore(BLOB_STORE, 'readonly', (store) => runRequest(store.get(imageId)));
  if (result && result.failed) return null;
  return result ? result.blob : null;
}

// The nuclear release valve for storage pressure: every project, every
// blob, gone. No automatic eviction logic — guessing which project to drop
// without asking is not something to do with athlete photos, so a person
// decides, explicitly, from the History screen (deleteProject for one
// project at a time, or this for all of them).
export async function clearAll() {
  const projectResult = await withStore(PROJECTS_STORE, 'readwrite', (store) => runRequest(store.clear()));
  const blobResult = await withStore(BLOB_STORE, 'readwrite', (store) => runRequest(store.clear()));
  const metaResult = await withStore(META_STORE, 'readwrite', (store) => runRequest(store.clear()));
  return !(projectResult?.failed || blobResult?.failed || metaResult?.failed);
}

// Best-effort: Safari's Intelligent Tracking Prevention can evict IndexedDB
// after 7 days with no user interaction, and any browser can evict under
// storage pressure. persist() asks not to be picked for that — it is not
// guaranteed (Safari in particular grants it rarely, if ever), so this is a
// courtesy call, not something callers should branch on.
export async function requestPersistence() {
  try {
    if (!navigator.storage?.persist) return null;
    return await navigator.storage.persist();
  } catch {
    return null;
  }
}

// Usage/quota as a fraction, for a warning banner — not for automatic
// action. 0.8 is this session's own threshold, not a spec'd browser
// constant: iOS quota is a moving share of free disk, so "80% of whatever
// that is right now" is a judgement call, flagged as such like the other
// engineering-judgement constants in this codebase (model.js,
// uncertainty.js).
export const STORAGE_WARNING_RATIO = 0.8;

export async function estimateStorageRatio() {
  try {
    if (!navigator.storage?.estimate) return null;
    const { usage, quota } = await navigator.storage.estimate();
    if (!quota) return null;
    return usage / quota;
  } catch {
    return null;
  }
}
